mapper.select:
SELECT r.rno,r.uno,pno,name,r_content,r_img,r_score,profile_img,TO_CHAR(r_created_at,'yyyy-mm-dd HH24:MI:SS) as dbday p.name FROM review JOIN users u ON r.uno=u.uno JOIN place p ON r.pno=p.pno WHERE pno=#{pno}
AND name LIKE'%'||#{name}||'%'
ORDER BY rno DESC OFFSET #{start} ROWS FETCH NEXT 3 ROWS ONLY
